"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["8263"],{40139(e,t,n){n.d(t,{Ay:()=>l,RM:()=>s});var i=n(74848),o=n(28453),a=n(66422);let s=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"teaching-you-to-trade-stocks-98-traditional-chinese-medicine-military-strategy-poetry-and-trading-2",children:"Teaching You to Trade Stocks 98: Traditional Chinese Medicine, Military Strategy, Poetry, and Trading 2"})}),"\n",(0,i.jsxs)(t.blockquote,{children:["\n",(0,i.jsx)(t.p,{children:"2008/2/4 19:51:49"}),"\n"]}),"\n",(0,i.jsxs)("div",{style:{color:"#FF0000",fontSize:"18px",fontWeight:"500"},children:[(0,i.jsx)(t.p,{children:"Before the holiday, I didn't plan to write another lesson. After all, there's no shortage of things to do at home during the holidays. But still, let me squeeze in a few words while I have time."}),(0,i.jsx)(t.p,{children:"Changing one's way of thinking is very difficult because the existence of a particular thinking pattern is often unnoticed even by oneself. Especially after a strong market move appears, those old bad habits resurface. The market reversal of the past few days is a perfect example."}),(0,i.jsx)(t.p,{children:"After a divergence \u2014 whether it's a consolidation divergence or a genuine divergence \u2014 the theory can only guarantee a pullback to the original hub. This is the correct way of thinking. As for what happens after the pullback, that involves prediction. The correct thinking is to completely classify all possible situations that may occur after the pullback, and based on the consequences corresponding to each classification, determine your own countermeasures."}),(0,i.jsx)(t.p,{children:"For example, last Friday afternoon's divergence was very obvious \u2014 anyone could have identified it in real time. After entering on this divergence and the market closed, there were two possible scenarios: either continuing to push upward above the hub, or pulling back down again. The first scenario means the line segment starting from 362 would continue to extend, while the second scenario would first destroy the line segment starting from 362. So these two situations are very simple \u2014 just wait until Monday's opening to determine in real time whether this line segment has been destroyed."}),(0,i.jsxs)("div",{style:{textAlign:"left"},children:[(0,i.jsx)("img",{src:(0,a.Ay)("/img/stocks/098/szzs_1f.gif")}),(0,i.jsx)("br",{}),(0,i.jsx)("br",{})]}),(0,i.jsx)(t.p,{children:"Note, this is strict theoretical thinking, completely unrelated to whether there's any news on Monday or whether there's positive news. In particular, if there were positive news yet the market still produced a move that destroyed the line segment starting from 362, then the problem would be serious. In reality, however, the market didn't destroy this line segment until 364. But at that point, there was no reason to exit \u2014 why? Because theoretically, the probability of this evolving into a line-segment-type rally was extremely high, unless the line segment starting from 363 broke below the 361 position. So afterward, you just needed to watch whether this line segment fell to that position, and obviously it didn't, so you continue holding."}),(0,i.jsx)(t.p,{children:"After 364 appeared and a new line segment unfolded, since this was already the second line-segment-type hub, you needed to watch for possible near-divergence. This depends on tomorrow's opening \u2014 if it cannot maintain a similar rate of upward movement, then it would be perfectly reasonable for this line-segment-type rally to end and form a 1-minute hub."}),(0,i.jsx)(t.p,{children:"You see, all the analysis above follows strict logical relationships. This is a necessary consequence of the theory and a correct way of thinking. Of course, whether a near-divergence of a line segment warrants selling some shares is a matter of personal preference and your operating timeframe."}),(0,i.jsx)(t.p,{children:"This is like warfare \u2014 you cannot assume that a certain hilltop will still be in your hands tomorrow and then arrange your forces based on that assumption. Whether the hilltop is in your hands is determined in the present moment. Of course, you can fight back and forth over a hilltop, but you cannot assume that this hilltop will be 100% in your hands at some future moment."}),(0,i.jsx)(t.p,{children:'This is also like Chinese medicine \u2014 you cannot assume your medicine will definitely have a certain effect. The effect is determined by "looking, listening, asking, and feeling the pulse" after the medicine has been taken, and the same patient\'s medicine must be adjusted as needed based on this continuous examination. Of course, you can also keep things unchanged \u2014 just as in an uptrend, you can hold your position. But once a reversal signal appears that exceeds your level, your operating threshold \u2014 that is, divergence \u2014 then your prescription must change, perhaps even drastically.'}),(0,i.jsx)(t.p,{children:"Therefore, if Monday had not produced today's positive news, your operating logic would not have changed at all. You would still act based on whether the chart at that time touched your operating classification boundaries. This is the correct way of thinking."}),(0,i.jsx)(t.p,{children:"In other words, when you are trading, all possible situations you may face subsequently, along with their countermeasures, must be crystal clear to you. Otherwise, you have no business trading. For a true operator, no situation is unexpected, because all situations have been completely classified, all corresponding countermeasures have been prepared in advance \u2014 you're simply waiting for the market itself to choose, to trigger the switches we have preset."}),(0,i.jsx)(t.p,{children:"Honestly, compared to Chinese medicine and warfare, stocks are the simplest. Why? Because with the existence of this ID's theory, the subsequent movements of stocks can all be strictly and uniquely given as unified complete classifications. Chinese medicine and warfare face potentially more complex situations. Especially in warfare, complete classification may only be a hypothetical possibility."}),(0,i.jsx)(t.p,{children:"If your thinking still hasn't turned around, then there's no need to continue studying. First, get your thinking straightened out."}),(0,i.jsx)(t.p,{children:"Some may ask: what if a pullback occurs and you can't exit your position bought at the divergence? Obviously, this is quite possible because with T+1, you may not be allowed to sell during the reaction time. However, a very simple countermeasure is: you must buy stocks that are stronger than the overall market \u2014 stocks that lead the market. This way, once the market reverses, these types of stocks will perform better than the market, naturally giving you enough room to make your choices."}),(0,i.jsx)(t.p,{children:"Note, the best choice is stocks that are slightly ahead of the market \u2014 not those completely contrary to the market. The latter often face the possibility of catching-up declines, or contrarian shakeouts. For example, today's 600737 is a perfect illustration. Of course, new stocks are also a good option, though this requires that they don't open too high and show clear signs of new capital entering. During a rally of a certain level, these generally exhibit relatively stable performance. Then there are stocks that adjusted ahead of the market \u2014 like that clever donkey this time, which was exactly this type."}),(0,i.jsx)(t.p,{children:"Of course, how to select stocks is a matter of experience that requires repeated practice before you develop intuition and sensitivity. Actually, stocks really aren't that complicated. Once you've developed that sensitivity, you open a stock's chart and can immediately tell whether this face is posturing and waiting to be favored \u2014 just like in a one-night stand, do you really need technical analysis to choose someone? Isn't it just a matter of one glance? The day you look at stocks with the same feeling as picking someone for a one-night stand, you're getting somewhere."})]})]})}function l(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(r,{...e})}):r(e)}},52862(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>c,assets:()=>h});var i=JSON.parse('{"id":"timeline/stocks/098","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/stocks/098.md","sourceDirName":"timeline/stocks","slug":"/timeline/stocks/098","permalink":"/en/timeline/stocks/098","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"098","title":"","hide_table_of_contents":true,"sidebar_label":"Teaching You Stock Trading 98: Traditional Chinese Medicine, Military Strategy, Poetry, and Trading 2 (2008/2/4 19:51:49)"},"sidebar":"timelineSidebar","previous":{"title":"A Chinese-Style Comedy Above the Annual Moving Average (2008/2/4 15:20:02)","permalink":"/en/timeline/economics/chinesecomedy"},"next":{"title":"Bearish Candle Welcoming Spring Gives the Stubborn Bulls a Vivid Lesson (2008/2/5 15:09:59)","permalink":"/en/timeline/economics/negativeline"}}'),o=n(74848),a=n(28453),s=n(40139);let r={id:"098",title:"",hide_table_of_contents:!0,sidebar_label:"Teaching You Stock Trading 98: Traditional Chinese Medicine, Military Strategy, Poetry, and Trading 2 (2008/2/4 19:51:49)"},l,h={},c=[...s.RM];function d(e){return(0,o.jsx)(s.Ay,{})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var i=n(96540);let o={},a=i.createContext(o);function s(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);